// The 'sshagent' service: the user's local SSH agent (SSH_AUTH_SOCK, or the one the app finds),
// reachable from the page as byte streams, for a plugin to forward it (the server plugin, to a
// tilr server's panes, like `ssh -A`). One backend and no fallback:
//
// - the Mac app registers `webkit.messageHandlers.tilrAgent` (Agent.swift). The page posts
//   { op, id?, data? }: 'probe' (is there an agent socket? the app answers 'ready' with
//   `available`, `path`, `error`), 'open' (a connection to the socket, named by `id`; the app
//   answers 'open', or 'close' with an error), 'data' (base64, written to the socket), 'close'
//   (drops it; the app may answer 'close' once). The app reports through a 'tilr-agent'
//   CustomEvent on `window`: 'ready', 'open', 'data' (`{ id, data }`, base64, ≤ 64 KiB a
//   chunk), 'close' (`{ id, error? }`). After a 'close', either way, nothing more for that id.
// - anywhere else (a browser, an iframe build, the tests) there is no handler: the service is
//   there all the same, `available` false and `connect()` rejecting, so a plugin can inject it
//   unconditionally and read `available`.
//
// A page reload drops the connections on the app's side: the service starts clean. The ids are a
// counter behind a random token of the service's, so a reloaded page (or plugin) never reuses
// one. A stream is the caller's: it leaves with the plugin that opened it (an effect in the
// caller's context, as popup() is); the service going closes all of them.
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { SshAgent as SshAgentApi, SshAgentStream, TilrPluginClass } from 'tilr'
import { nativeChannel } from 'tilr/native'

/** The app's message handler, and the event it answers with. */
export const HANDLER = 'tilrAgent'
export const EVENT = 'tilr-agent'

/** How long a probe waits for the app's 'ready' before it settles for what it knew. */
const PROBE_TIMEOUT = 5000
/** The bytes per 'data' post: the app's own chunk size. */
const CHUNK = 64 * 1024

/** What arrives with a 'tilr-agent' event. */
export type NativeEvent =
  | { type: 'ready', available: boolean, path?: string, error?: string }
  | { type: 'open', id: string }
  | { type: 'data', id: string, data: string }
  | { type: 'close', id: string, error?: string }

// --- base64: the bridge's encoding of bytes, both ways ---

/** `bytes` as base64; a binary string built a slice at a time (no argument-count limit). */
export function toBase64(bytes: Uint8Array): string {
  let binary = ''
  for (let at = 0; at < bytes.length; at += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(at, at + 0x8000))
  }
  return btoa(binary)
}

/** The bytes of a base64 string. */
export function fromBase64(text: string): Uint8Array {
  const binary = atob(text)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  return bytes
}

/** A random hex token: the prefix of this service's ids. */
function token(): string {
  const bytes = new Uint8Array(6)
  crypto.getRandomValues(bytes)
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
}

type Listener = (data: Uint8Array | null, error?: string) => void

/** One connection to the agent. Bytes that arrive before anyone subscribes wait for the first
 *  subscriber; so does the end. */
export class Stream implements SshAgentStream {
  readonly id: string
  private post: (body: Record<string, unknown>) => void
  private onClose: (stream: Stream) => void
  private listeners = new Set<Listener>()
  private pending: Uint8Array[] = []
  private ended = false
  private error: string | undefined
  /** False until the app's 'open' (or the end). */
  opened = false

  constructor(id: string, post: (body: Record<string, unknown>) => void, onClose: (stream: Stream) => void) {
    this.id = id
    this.post = post
    this.onClose = onClose
  }

  get closed(): boolean { return this.ended }

  send(data: Uint8Array): void {
    if (this.ended || !(data instanceof Uint8Array) || data.length === 0) return
    for (let at = 0; at < data.length; at += CHUNK) {
      this.post({ op: 'data', id: this.id, data: toBase64(data.subarray(at, at + CHUNK)) })
    }
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener)
    // The first subscriber gets what came before it.
    if (this.listeners.size === 1) {
      const pending = this.pending
      this.pending = []
      for (const bytes of pending) this.call(listener, bytes)
      if (this.ended) this.call(listener, null, this.error)
    } else if (this.ended) {
      this.call(listener, null, this.error)
    }
    return () => { this.listeners.delete(listener) }
  }

  close(): void {
    if (this.ended) return
    this.post({ op: 'close', id: this.id })
    this.end()
  }

  /** Bytes from the app. */
  receive(bytes: Uint8Array): void {
    if (this.ended) return
    if (!this.listeners.size) { this.pending.push(bytes); return }
    for (const listener of [...this.listeners]) this.call(listener, bytes)
  }

  /** The connection is over: `null` (and the error) to the listeners, once. */
  end(error?: string): void {
    if (this.ended) return
    this.ended = true
    this.error = error
    this.onClose(this)
    if (!this.listeners.size) return
    for (const listener of [...this.listeners]) this.call(listener, null, error)
    this.listeners.clear()
  }

  private call(listener: Listener, data: Uint8Array | null, error?: string): void {
    try {
      if (data === null && error !== undefined) listener(null, error)
      else listener(data)
    } catch (e) { console.error(e) }
  }
}

class SshAgentService extends Service implements SshAgentApi {
  static provide = 'sshagent'
  static author = 'dan'
  static tags = ['core']
  static version = __TILR_VERSION__
  static locked = true

  declare state: {
    post: ((body: Record<string, unknown>) => void) | null
    available: boolean
    path: string | null
    /** Why the last probe found no agent (the app's error), for connect()'s rejection. */
    error: string | null
    /** The probe in flight: the answer to the next 'ready'. */
    probing: { promise: Promise<boolean>, resolve: (available: boolean) => void } | null
    token: string
    next: number
    streams: Map<string, Stream>
    /** The connects waiting for the app's 'open'. */
    opening: Map<string, { resolve: () => void, reject: (error: Error) => void }>
    live: boolean
  }

  constructor(ctx: Context) {
    super(ctx, SshAgentService.provide)
    const channel = nativeChannel<NativeEvent>(HANDLER, EVENT)
    this.state = {
      post: channel ? body => channel.post(body) : null,
      available: false,
      path: null,
      error: null,
      probing: null,
      token: token(),
      next: 0,
      streams: new Map(),
      opening: new Map(),
      live: true,
    }
    if (!channel) return

    ctx.effect(() => {
      const off = channel.listen(event => this.receive(ctx, event))
      void this.probe()
      return () => {
        off()
        this.state.live = false
        this.state.probing?.resolve(false)
        this.state.probing = null
        for (const { reject } of this.state.opening.values()) reject(new Error('sshagent: the service went'))
        this.state.opening.clear()
        // The service going: its connections with it (the app would keep them for a page that forgot them).
        for (const stream of [...this.state.streams.values()]) stream.close()
      }
    }, 'sshagent: app events')
  }

  get available(): boolean { return this.state.available }
  get path(): string | null { return this.state.path }

  probe(): Promise<boolean> {
    const { post } = this.state
    if (!post || !this.state.live) return Promise.resolve(false)
    if (this.state.probing) return this.state.probing.promise
    let resolve!: (available: boolean) => void
    const promise = new Promise<boolean>(r => { resolve = r })
    const timer = setTimeout(() => {
      if (this.state.probing?.promise === promise) this.state.probing = null
      resolve(this.state.available)
    }, PROBE_TIMEOUT)
    this.state.probing = { promise, resolve: available => { clearTimeout(timer); resolve(available) } }
    post({ op: 'probe' })
    return promise
  }

  async connect(): Promise<SshAgentStream> {
    // this.ctx is the caller's context, now (not after an await): the stream is its effect.
    const caller = this.ctx
    const { post } = this.state
    if (!post) throw new Error('no SSH agent bridge: not the Mac app')
    if (this.state.probing) await this.state.probing.promise
    if (!this.state.available) {
      throw new Error(this.state.error ? `no SSH agent socket found: ${this.state.error}` : 'no SSH agent socket found')
    }
    const id = `${this.state.token}-${++this.state.next}`
    const { streams, opening } = this.state
    // The caller's effect, dropped when the stream ends first (nothing left in its plugin).
    let release: (() => void) | null = null
    const stream = new Stream(id, post, closed => {
      if (streams.get(closed.id) === closed) streams.delete(closed.id)
      opening.get(closed.id)?.reject(new Error('sshagent: the connection was closed before it opened'))
      opening.delete(closed.id)
      const drop = release
      release = null
      drop?.()
    })
    streams.set(id, stream)
    try {
      const off = caller.effect(() => () => {
        release = null
        stream.close()
      }, 'sshagent.connect()')
      if (!stream.closed) release = () => { void off() }
    } catch { /* a caller that is not running: the stream is its own */ }
    const opened = new Promise<void>((resolve, reject) => opening.set(id, { resolve, reject }))
    post({ op: 'open', id })
    await opened
    return stream
  }

  private receive(ctx: Context, detail: NativeEvent | null | undefined): void {
    if (!detail || typeof detail !== 'object' || !this.state.live) return
    switch (detail.type) {
      case 'ready': {
        const available = !!detail.available
        const path = available && typeof detail.path === 'string' ? detail.path : null
        this.state.error = available ? null : detail.error ?? null
        const changed = available !== this.state.available || path !== this.state.path
        this.state.available = available
        this.state.path = path
        const probing = this.state.probing
        this.state.probing = null
        probing?.resolve(available)
        if (changed) ctx.emit('sshagent/change')
        return
      }
      case 'open': {
        const stream = this.state.streams.get(detail.id)
        const waiting = this.state.opening.get(detail.id)
        this.state.opening.delete(detail.id)
        if (stream) stream.opened = true
        waiting?.resolve()
        return
      }
      case 'data': {
        const stream = this.state.streams.get(detail.id)
        if (!stream || typeof detail.data !== 'string') return
        let bytes: Uint8Array
        try { bytes = fromBase64(detail.data) } catch { return }
        stream.receive(bytes)
        return
      }
      case 'close': {
        const error = typeof detail.error === 'string' ? detail.error : undefined
        const waiting = this.state.opening.get(detail.id)
        this.state.opening.delete(detail.id)
        waiting?.reject(new Error(error ? `sshagent: ${error}` : 'sshagent: the agent closed the connection'))
        this.state.streams.get(detail.id)?.end(error)
        return
      }
    }
  }
}

export default SshAgentService satisfies TilrPluginClass
